// Ambil metadata audio dari update Telegram (voice note, file audio, video note,
// atau document ber-mime audio/video) dan normalkan jadi satu bentuk.
const update = $input.first().json;
const message = update.message ?? update.channel_post ?? update;

const candidates = [
  ['voice', message.voice],
  ['audio', message.audio],
  ['video_note', message.video_note],
];

let kind = null;
let media = null;
for (const [name, value] of candidates) {
  if (value && value.file_id) {
    kind = name;
    media = value;
    break;
  }
}

if (!media && message.document?.file_id) {
  const mime = String(message.document.mime_type ?? '');
  if (/^(audio|video)\//.test(mime)) {
    kind = 'document';
    media = message.document;
  }
}

const chatId = String(message.chat?.id ?? '');
const sentAt = message.date ? new Date(message.date * 1000).toISOString() : new Date().toISOString();

return [
  {
    json: {
      has_audio: Boolean(media),
      kind,
      chat_id: chatId,
      message_id: message.message_id ?? null,
      from: message.from?.first_name ?? '',
      caption: String(message.caption ?? '').trim(),
      sent_at: sentAt,
      file_id: media?.file_id ?? '',
      file_name: media?.file_name ?? '',
      mime_type: media?.mime_type ?? '',
      file_size: Number(media?.file_size ?? 0),
      duration_sec: Number(media?.duration ?? 0),
    },
  },
];

// Gabungkan hasil transkripsi semua part audio kembali jadi satu teks.
// Node ini menerima item dari jalur Groq maupun jalur fallback OpenAI, jadi
// urutannya dipulihkan lewat index part-nya, bukan lewat urutan item.
const items = $input.all();
const rows = [];

for (let i = 0; i < items.length; i++) {
  const json = items[i].json ?? {};

  let index = i;
  try {
    const matched = $('Split Parts').itemMatching(i);
    const value = Number(matched?.json?.index);
    if (Number.isFinite(value)) index = value;
  } catch (error) {
    // Paired-item tidak bisa ditelusuri (mis. provider mengubah bentuk item) —
    // pakai urutan kedatangan sebagai perkiraan terbaik.
    index = i;
  }

  const text = typeof json.text === 'string' ? json.text : (json.transcript ?? '');
  rows.push({ index, text: String(text).trim() });
}

rows.sort((a, b) => a.index - b.index);

const transcriptRaw = rows
  .map((row) => row.text)
  .filter(Boolean)
  .join('\n\n')
  .trim();

const meta = $('Extract Audio').first().json;

return [
  {
    json: {
      chat_id: meta.chat_id,
      message_id: meta.message_id,
      sent_at: meta.sent_at,
      caption: meta.caption,
      duration_sec: meta.duration_sec,
      part_count: rows.length,
      transcript_raw: transcriptRaw,
      has_transcript: transcriptRaw.length > 0,
    },
  },
];

// Susun body request LLM untuk koreksi istilah.
// Transkrip adalah input bebas, jadi body-nya dirakit sebagai objek lalu
// di-JSON.stringify() di sini dan dikirim sebagai Raw body oleh HTTP Request node.
const SYSTEM_PROMPT = "Kamu adalah editor transkrip Bahasa Indonesia untuk rekaman rapat/brainstorm bisnis.\n\nTugasmu HANYA memperbaiki hasil speech-to-text, bukan menulis ulang.\n\nATURAN WAJIB:\n1. Perbaiki typo, salah dengar, dan ejaan istilah/brand memakai kamus di bawah.\n2. Perbaiki tanda baca, kapitalisasi, dan pemenggalan kalimat agar mudah dibaca.\n3. Hapus filler yang tidak bermakna (eh, emm, anu, gitu ya) bila mengganggu, tapi JANGAN memadatkan isi.\n4. JANGAN mengubah makna, JANGAN menambah informasi baru, JANGAN menyimpulkan, JANGAN menerjemahkan.\n5. Kalau sebuah kata benar-benar tidak jelas, biarkan apa adanya — jangan menebak fakta.\n6. Pertahankan angka, nominal, tanggal, dan nama orang persis seperti aslinya.\n7. Pisahkan menjadi paragraf saat topik berganti.\n\nKAMUS EJAAN (ini ejaan yang benar — pakai persis seperti ini):\nBrand & nama produk: Zaneva, Elyasr, Be.Syari, Oberbe, Muslimah Swimwear, Yaumiah\nIstilah bisnis: ROAS, ROI, HPP, omzet, margin, gross profit, net profit, cashflow, CPA, CPM, CTR, AOV, SKU, COD, closing, reseller, affiliate, endorse, marketplace, funnel, landing page, retargeting, budget harian, content plan, stock opname, pre-order, restock, supplier, invoice, purchase order, cash on delivery\n\nFORMAT OUTPUT:\nBalas HANYA dengan teks transkrip yang sudah diperbaiki. Tanpa pembuka, tanpa penutup, tanpa penjelasan, tanpa tanda kutip pembungkus, tanpa blok kode.";

const config = $('Config').first().json;
const source = $input.first().json;
const transcript = String(source.transcript_raw ?? '').trim();

const body = {
  model: config.llm_model,
  temperature: Number(config.llm_temperature_correct ?? 0.1),
  messages: [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: transcript },
  ],
};

return [
  {
    json: {
      ...source,
      llm_url: `${String(config.llm_base_url).replace(/\/+$/, '')}/chat/completions`,
      body: JSON.stringify(body),
    },
  },
];

// Ambil teks balasan LLM dari bentuk respons OpenAI-compatible.
const response = $input.first().json;
const previous = $('Build Correction Request').first().json;

const choice = response?.choices?.[0];
const raw = choice?.message?.content ?? choice?.text ?? '';

const corrected = (Array.isArray(raw) ? raw.map((part) => part?.text ?? '').join('') : String(raw))
  // Sebagian model membungkus jawaban dalam blok kode meski sudah dilarang.
  .replace(/^\s*```[a-z]*\s*\n?/i, '')
  .replace(/\n?```\s*$/i, '')
  .trim();

const fallbackUsed = corrected.length === 0;

return [
  {
    json: {
      chat_id: previous.chat_id,
      message_id: previous.message_id,
      sent_at: previous.sent_at,
      caption: previous.caption,
      duration_sec: previous.duration_sec,
      part_count: previous.part_count,
      transcript_raw: previous.transcript_raw,
      // Kalau LLM balas kosong, lebih baik pakai transkrip mentah daripada gagal.
      transcript_corrected: fallbackUsed ? previous.transcript_raw : corrected,
      correction_applied: !fallbackUsed,
    },
  },
];

// Susun body request LLM untuk ringkasan + outline mind map.
// Node yang sama dipakai untuk percobaan pertama dan percobaan ulang; saat
// RETRY_MODE aktif, instruksi tambahan soal JSON valid ikut dikirim.
const SYSTEM_PROMPT = "Kamu adalah notulis profesional. Dari transkrip rapat/brainstorm Bahasa Indonesia, hasilkan ringkasan dan outline mind map.\n\nATURAN ISI:\n1. Semua output dalam Bahasa Indonesia.\n2. Hanya gunakan informasi yang ada di transkrip. Dilarang mengarang, menebak, atau menambah rekomendasi yang tidak diucapkan.\n3. `summary` = 3-6 kalimat padat berisi inti pembahasan dan keputusan. Bukan daftar, bukan bullet.\n4. `title` = judul singkat maksimal 8 kata yang menggambarkan isi rekaman.\n5. `outline` = struktur mind map:\n   - Level 1: 1 node akar saja, isinya sama dengan `title`.\n   - Level 2: 3-7 tema besar.\n   - Level 3: detail/poin di bawah tiap tema, maksimal 6 per tema.\n   - MAKSIMAL 3 level. Dilarang membuat level ke-4.\n6. Teks tiap node maksimal 60 karakter, ringkas seperti judul, tanpa tanda baca di akhir.\n7. Kalau ada action item / keputusan, jadikan salah satu tema level 2 tersendiri.\n8. Jangan menaruh markdown (#, *, -) di dalam nilai `title`.\n\nFORMAT OUTPUT — balas HANYA dengan objek JSON valid, tanpa blok kode, tanpa teks lain:\n{\n  \"title\": \"string\",\n  \"summary\": \"string\",\n  \"outline\": [\n    {\n      \"title\": \"string\",\n      \"children\": [\n        { \"title\": \"string\", \"children\": [ { \"title\": \"string\" } ] }\n      ]\n    }\n  ]\n}\n\nKAMUS EJAAN (pakai persis seperti ini bila muncul):\nBrand & nama produk: Zaneva, Elyasr, Be.Syari, Oberbe, Muslimah Swimwear, Yaumiah\nIstilah bisnis: ROAS, ROI, HPP, omzet, margin, gross profit, net profit, cashflow, CPA, CPM, CTR, AOV, SKU, COD, closing, reseller, affiliate, endorse, marketplace, funnel, landing page, retargeting, budget harian, content plan, stock opname, pre-order, restock, supplier, invoice, purchase order, cash on delivery";
const RETRY_MODE = false;

const config = $('Config').first().json;
const source = RETRY_MODE ? $('Parse Correction').first().json : $input.first().json;
const transcript = String(source.transcript_corrected ?? source.transcript_raw ?? '').trim();

const messages = [{ role: 'system', content: SYSTEM_PROMPT }];

if (RETRY_MODE) {
  messages.push({
    role: 'system',
    content:
      'PERCOBAAN ULANG. Balasan sebelumnya bukan JSON valid. Balas HANYA satu objek JSON valid ' +
      'sesuai skema di atas — tanpa blok kode, tanpa komentar, tanpa teks pembuka atau penutup. ' +
      'Pastikan seluruh tanda kurung dan tanda kutip tertutup rapi.',
  });
}

messages.push({ role: 'user', content: transcript });

const body = {
  model: config.llm_model,
  temperature: RETRY_MODE ? 0 : Number(config.llm_temperature_outline ?? 0.3),
  messages,
};

// Beberapa provider OpenAI-compatible belum mendukung response_format —
// matikan lewat field `llm_json_mode` di node Config kalau provider menolak.
if (config.llm_json_mode === true || config.llm_json_mode === 'true') {
  body.response_format = { type: 'json_object' };
}

return [
  {
    json: {
      ...source,
      llm_url: `${String(config.llm_base_url).replace(/\/+$/, '')}/chat/completions`,
      body: JSON.stringify(body),
    },
  },
];

// Parse balasan LLM jadi { title, summary, outline }.
// Node ini sengaja tidak pernah melempar error: kalau JSON-nya rusak, ia hanya
// menandai outline_valid = false supaya alur bisa retry / turun ke mode teks.
const SOURCE_NODE = "Build Outline Request";

const MAX_DEPTH = 3;
const MAX_CHILDREN = 8;
const MAX_LABEL = 80;

const response = $input.first().json;
const previous = $(SOURCE_NODE).first().json;

const choice = response?.choices?.[0];
const rawContent = choice?.message?.content ?? choice?.text ?? '';
const text = (Array.isArray(rawContent) ? rawContent.map((p) => p?.text ?? '').join('') : String(rawContent)).trim();

function extractJson(input) {
  const unfenced = input
    .replace(/^\s*```[a-z]*\s*\n?/i, '')
    .replace(/\n?```\s*$/i, '')
    .trim();

  try {
    return JSON.parse(unfenced);
  } catch (error) {
    // Model kadang menambahkan kalimat pembuka — ambil objek JSON terluar saja.
    const start = unfenced.indexOf('{');
    const end = unfenced.lastIndexOf('}');
    if (start === -1 || end <= start) return null;
    try {
      return JSON.parse(unfenced.slice(start, end + 1));
    } catch (innerError) {
      return null;
    }
  }
}

function cleanLabel(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s>#*+-]+/, '')
    .replace(/^\d+\.\s+/, '')
    .trim()
    .slice(0, MAX_LABEL);
}

function normalizeOutline(nodes, depth) {
  if (!Array.isArray(nodes) || depth > MAX_DEPTH) return [];
  const result = [];
  for (const node of nodes.slice(0, MAX_CHILDREN)) {
    const label = cleanLabel(typeof node === 'string' ? node : (node?.title ?? node?.name));
    if (!label) continue;
    const children = typeof node === 'string' ? [] : normalizeOutline(node?.children, depth + 1);
    result.push(children.length ? { title: label, children } : { title: label });
  }
  return result;
}

const parsed = extractJson(text);
const outline = normalizeOutline(parsed?.outline, 1);
const summary = String(parsed?.summary ?? '').trim();
const title = cleanLabel(parsed?.title) || cleanLabel(outline[0]?.title) || 'Catatan Suara';

const outlineValid = outline.length > 0 && summary.length > 0;

return [
  {
    json: {
      chat_id: previous.chat_id,
      message_id: previous.message_id,
      sent_at: previous.sent_at,
      caption: previous.caption,
      duration_sec: previous.duration_sec,
      part_count: previous.part_count,
      transcript_raw: previous.transcript_raw,
      transcript_corrected: previous.transcript_corrected,
      correction_applied: previous.correction_applied,
      outline_valid: outlineValid,
      title,
      summary: summary || String(previous.transcript_corrected ?? '').slice(0, 600),
      outline,
      llm_raw_preview: outlineValid ? '' : text.slice(0, 400),
    },
  },
];

// Susun body request LLM untuk ringkasan + outline mind map.
// Node yang sama dipakai untuk percobaan pertama dan percobaan ulang; saat
// RETRY_MODE aktif, instruksi tambahan soal JSON valid ikut dikirim.
const SYSTEM_PROMPT = "Kamu adalah notulis profesional. Dari transkrip rapat/brainstorm Bahasa Indonesia, hasilkan ringkasan dan outline mind map.\n\nATURAN ISI:\n1. Semua output dalam Bahasa Indonesia.\n2. Hanya gunakan informasi yang ada di transkrip. Dilarang mengarang, menebak, atau menambah rekomendasi yang tidak diucapkan.\n3. `summary` = 3-6 kalimat padat berisi inti pembahasan dan keputusan. Bukan daftar, bukan bullet.\n4. `title` = judul singkat maksimal 8 kata yang menggambarkan isi rekaman.\n5. `outline` = struktur mind map:\n   - Level 1: 1 node akar saja, isinya sama dengan `title`.\n   - Level 2: 3-7 tema besar.\n   - Level 3: detail/poin di bawah tiap tema, maksimal 6 per tema.\n   - MAKSIMAL 3 level. Dilarang membuat level ke-4.\n6. Teks tiap node maksimal 60 karakter, ringkas seperti judul, tanpa tanda baca di akhir.\n7. Kalau ada action item / keputusan, jadikan salah satu tema level 2 tersendiri.\n8. Jangan menaruh markdown (#, *, -) di dalam nilai `title`.\n\nFORMAT OUTPUT — balas HANYA dengan objek JSON valid, tanpa blok kode, tanpa teks lain:\n{\n  \"title\": \"string\",\n  \"summary\": \"string\",\n  \"outline\": [\n    {\n      \"title\": \"string\",\n      \"children\": [\n        { \"title\": \"string\", \"children\": [ { \"title\": \"string\" } ] }\n      ]\n    }\n  ]\n}\n\nKAMUS EJAAN (pakai persis seperti ini bila muncul):\nBrand & nama produk: Zaneva, Elyasr, Be.Syari, Oberbe, Muslimah Swimwear, Yaumiah\nIstilah bisnis: ROAS, ROI, HPP, omzet, margin, gross profit, net profit, cashflow, CPA, CPM, CTR, AOV, SKU, COD, closing, reseller, affiliate, endorse, marketplace, funnel, landing page, retargeting, budget harian, content plan, stock opname, pre-order, restock, supplier, invoice, purchase order, cash on delivery";
const RETRY_MODE = true;

const config = $('Config').first().json;
const source = RETRY_MODE ? $('Parse Correction').first().json : $input.first().json;
const transcript = String(source.transcript_corrected ?? source.transcript_raw ?? '').trim();

const messages = [{ role: 'system', content: SYSTEM_PROMPT }];

if (RETRY_MODE) {
  messages.push({
    role: 'system',
    content:
      'PERCOBAAN ULANG. Balasan sebelumnya bukan JSON valid. Balas HANYA satu objek JSON valid ' +
      'sesuai skema di atas — tanpa blok kode, tanpa komentar, tanpa teks pembuka atau penutup. ' +
      'Pastikan seluruh tanda kurung dan tanda kutip tertutup rapi.',
  });
}

messages.push({ role: 'user', content: transcript });

const body = {
  model: config.llm_model,
  temperature: RETRY_MODE ? 0 : Number(config.llm_temperature_outline ?? 0.3),
  messages,
};

// Beberapa provider OpenAI-compatible belum mendukung response_format —
// matikan lewat field `llm_json_mode` di node Config kalau provider menolak.
if (config.llm_json_mode === true || config.llm_json_mode === 'true') {
  body.response_format = { type: 'json_object' };
}

return [
  {
    json: {
      ...source,
      llm_url: `${String(config.llm_base_url).replace(/\/+$/, '')}/chat/completions`,
      body: JSON.stringify(body),
    },
  },
];

// Parse balasan LLM jadi { title, summary, outline }.
// Node ini sengaja tidak pernah melempar error: kalau JSON-nya rusak, ia hanya
// menandai outline_valid = false supaya alur bisa retry / turun ke mode teks.
const SOURCE_NODE = "Build Outline Retry Request";

const MAX_DEPTH = 3;
const MAX_CHILDREN = 8;
const MAX_LABEL = 80;

const response = $input.first().json;
const previous = $(SOURCE_NODE).first().json;

const choice = response?.choices?.[0];
const rawContent = choice?.message?.content ?? choice?.text ?? '';
const text = (Array.isArray(rawContent) ? rawContent.map((p) => p?.text ?? '').join('') : String(rawContent)).trim();

function extractJson(input) {
  const unfenced = input
    .replace(/^\s*```[a-z]*\s*\n?/i, '')
    .replace(/\n?```\s*$/i, '')
    .trim();

  try {
    return JSON.parse(unfenced);
  } catch (error) {
    // Model kadang menambahkan kalimat pembuka — ambil objek JSON terluar saja.
    const start = unfenced.indexOf('{');
    const end = unfenced.lastIndexOf('}');
    if (start === -1 || end <= start) return null;
    try {
      return JSON.parse(unfenced.slice(start, end + 1));
    } catch (innerError) {
      return null;
    }
  }
}

function cleanLabel(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s>#*+-]+/, '')
    .replace(/^\d+\.\s+/, '')
    .trim()
    .slice(0, MAX_LABEL);
}

function normalizeOutline(nodes, depth) {
  if (!Array.isArray(nodes) || depth > MAX_DEPTH) return [];
  const result = [];
  for (const node of nodes.slice(0, MAX_CHILDREN)) {
    const label = cleanLabel(typeof node === 'string' ? node : (node?.title ?? node?.name));
    if (!label) continue;
    const children = typeof node === 'string' ? [] : normalizeOutline(node?.children, depth + 1);
    result.push(children.length ? { title: label, children } : { title: label });
  }
  return result;
}

const parsed = extractJson(text);
const outline = normalizeOutline(parsed?.outline, 1);
const summary = String(parsed?.summary ?? '').trim();
const title = cleanLabel(parsed?.title) || cleanLabel(outline[0]?.title) || 'Catatan Suara';

const outlineValid = outline.length > 0 && summary.length > 0;

return [
  {
    json: {
      chat_id: previous.chat_id,
      message_id: previous.message_id,
      sent_at: previous.sent_at,
      caption: previous.caption,
      duration_sec: previous.duration_sec,
      part_count: previous.part_count,
      transcript_raw: previous.transcript_raw,
      transcript_corrected: previous.transcript_corrected,
      correction_applied: previous.correction_applied,
      outline_valid: outlineValid,
      title,
      summary: summary || String(previous.transcript_corrected ?? '').slice(0, 600),
      outline,
      llm_raw_preview: outlineValid ? '' : text.slice(0, 400),
    },
  },
];

// Ubah outline JSON jadi markdown heading (#, ##, ###) lalu rakit body request
// untuk render service. Body di-JSON.stringify() di sini dan dikirim sebagai
// Raw body karena isinya teks bebas dari LLM.
const MAX_DEPTH = 3;

const config = $('Config').first().json;
const source = $input.first().json;

function cleanLabel(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s>#*+-]+/, '')
    .replace(/^\d+\.\s+/, '')
    .trim();
}

const entries = [];

function walk(nodes, depth) {
  for (const node of Array.isArray(nodes) ? nodes : []) {
    const label = cleanLabel(typeof node === 'string' ? node : (node?.title ?? node?.name));
    if (!label) continue;

    if (depth <= MAX_DEPTH) {
      entries.push({ kind: 'heading', text: `${'#'.repeat(depth)} ${label}` });
    } else {
      // Pengaman kalau LLM tetap mengirim level 4+: turunkan jadi bullet
      // supaya tidak ada poin yang hilang dari mind map.
      entries.push({ kind: 'bullet', text: `${'  '.repeat(depth - MAX_DEPTH - 1)}- ${label}` });
    }
    walk(typeof node === 'string' ? null : node?.children, depth + 1);
  }
}

walk(source.outline, 1);

const lines = [];
entries.forEach((entry, i) => {
  if (i > 0 && (entry.kind === 'heading' || entries[i - 1].kind === 'heading')) lines.push('');
  lines.push(entry.text);
});

const markdown = lines.join('\n').trim();

const body = {
  markdown,
  width: Number(config.mindmap_width ?? 1600),
  theme: String(config.mindmap_theme ?? 'light'),
};

return [
  {
    json: {
      ...source,
      markdown,
      render_url: `${String(config.render_base_url).replace(/\/+$/, '')}/render`,
      body: JSON.stringify(body),
    },
  },
];

// Rakit pesan ringkasan untuk Telegram (parse_mode HTML).
const WITH_MINDMAP = true;
const TELEGRAM_LIMIT = 4000;

function pick(nodeName) {
  try {
    return $(nodeName).first().json ?? null;
  } catch (error) {
    return null;
  }
}

// Node ini dipakai oleh jalur dengan dan tanpa mind map, jadi sumber datanya
// dicari dari kandidat yang benar-benar sempat berjalan.
const candidates = ['Outline to Markdown', 'Parse Outline Retry', 'Parse Outline']
  .map(pick)
  .filter(Boolean);
const data = candidates.find((item) => item.outline_valid) ?? candidates[0] ?? pick('Parse Correction') ?? {};

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatDuration(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  if (!total) return '';
  const minutes = Math.floor(total / 60);
  const rest = total % 60;
  return minutes ? `${minutes} mnt ${rest} dtk` : `${rest} dtk`;
}

function formatDate(iso) {
  try {
    return new Date(iso).toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta',
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch (error) {
    return '';
  }
}

let durationSec = Number(data.duration_sec ?? 0);
const prepared = pick('Prepare Audio');
if (!durationSec && prepared?.durationSec) durationSec = Number(prepared.durationSec);

const metaParts = [formatDuration(durationSec), formatDate(data.sent_at)].filter(Boolean);

const lines = [`🗒 <b>${escapeHtml(data.title ?? 'Catatan Suara')}</b>`];
if (metaParts.length) lines.push(`<i>${escapeHtml(metaParts.join(' · '))}</i>`);
lines.push('', escapeHtml(data.summary ?? '').trim());

const outline = Array.isArray(data.outline) ? data.outline : [];
const themes = outline.length === 1 && Array.isArray(outline[0]?.children) ? outline[0].children : outline;

if (themes.length) {
  lines.push('', '<b>Poin utama</b>');
  for (const theme of themes) {
    lines.push(`• <b>${escapeHtml(theme?.title)}</b>`);
    for (const child of Array.isArray(theme?.children) ? theme.children : []) {
      lines.push(`   ◦ ${escapeHtml(child?.title)}`);
    }
  }
}

if (!WITH_MINDMAP) {
  lines.push('', '<i>⚠️ Mind map gagal dibuat kali ini — ringkasan tetap dikirim.</i>');
}

let text = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
if (text.length > TELEGRAM_LIMIT) {
  text = `${text.slice(0, TELEGRAM_LIMIT - 30).trim()}\n\n<i>… (dipotong)</i>`;
}

return [
  {
    json: {
      chat_id: data.chat_id ?? $('Extract Audio').first().json.chat_id,
      title: data.title ?? 'Catatan Suara',
      summary_text: text,
    },
  },
];

// Rakit pesan ringkasan untuk Telegram (parse_mode HTML).
const WITH_MINDMAP = false;
const TELEGRAM_LIMIT = 4000;

function pick(nodeName) {
  try {
    return $(nodeName).first().json ?? null;
  } catch (error) {
    return null;
  }
}

// Node ini dipakai oleh jalur dengan dan tanpa mind map, jadi sumber datanya
// dicari dari kandidat yang benar-benar sempat berjalan.
const candidates = ['Outline to Markdown', 'Parse Outline Retry', 'Parse Outline']
  .map(pick)
  .filter(Boolean);
const data = candidates.find((item) => item.outline_valid) ?? candidates[0] ?? pick('Parse Correction') ?? {};

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatDuration(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  if (!total) return '';
  const minutes = Math.floor(total / 60);
  const rest = total % 60;
  return minutes ? `${minutes} mnt ${rest} dtk` : `${rest} dtk`;
}

function formatDate(iso) {
  try {
    return new Date(iso).toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta',
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch (error) {
    return '';
  }
}

let durationSec = Number(data.duration_sec ?? 0);
const prepared = pick('Prepare Audio');
if (!durationSec && prepared?.durationSec) durationSec = Number(prepared.durationSec);

const metaParts = [formatDuration(durationSec), formatDate(data.sent_at)].filter(Boolean);

const lines = [`🗒 <b>${escapeHtml(data.title ?? 'Catatan Suara')}</b>`];
if (metaParts.length) lines.push(`<i>${escapeHtml(metaParts.join(' · '))}</i>`);
lines.push('', escapeHtml(data.summary ?? '').trim());

const outline = Array.isArray(data.outline) ? data.outline : [];
const themes = outline.length === 1 && Array.isArray(outline[0]?.children) ? outline[0].children : outline;

if (themes.length) {
  lines.push('', '<b>Poin utama</b>');
  for (const theme of themes) {
    lines.push(`• <b>${escapeHtml(theme?.title)}</b>`);
    for (const child of Array.isArray(theme?.children) ? theme.children : []) {
      lines.push(`   ◦ ${escapeHtml(child?.title)}`);
    }
  }
}

if (!WITH_MINDMAP) {
  lines.push('', '<i>⚠️ Mind map gagal dibuat kali ini — ringkasan tetap dikirim.</i>');
}

let text = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
if (text.length > TELEGRAM_LIMIT) {
  text = `${text.slice(0, TELEGRAM_LIMIT - 30).trim()}\n\n<i>… (dipotong)</i>`;
}

return [
  {
    json: {
      chat_id: data.chat_id ?? $('Extract Audio').first().json.chat_id,
      title: data.title ?? 'Catatan Suara',
      summary_text: text,
    },
  },
];

// Kirim transkrip bersih: sebagai pesan biasa kalau pendek, sebagai file .txt
// kalau panjang (batas pesan Telegram 4096 karakter).
const config = $('Config').first().json;
const data = $('Parse Correction').first().json;

const transcript = String(data.transcript_corrected ?? data.transcript_raw ?? '').trim();
const limit = Number(config.max_transcript_inline ?? 3000);
const chatId = data.chat_id ?? $('Extract Audio').first().json.chat_id;

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function stamp(iso) {
  const date = new Date(iso ?? Date.now());
  const valid = Number.isNaN(date.getTime()) ? new Date() : date;
  return valid.toISOString().slice(0, 16).replace('T', '-').replace(':', '');
}

if (transcript.length <= limit) {
  return [
    {
      json: {
        chat_id: chatId,
        is_file: false,
        transcript_text: `📝 <b>Transkrip</b>\n\n${escapeHtml(transcript)}`,
      },
    },
  ];
}

const header = [
  data.title ? `Judul: ${data.title}` : null,
  `Tanggal: ${data.sent_at ?? ''}`,
  '',
  '',
].filter((line) => line !== null);

const content = `${header.join('\n')}${transcript}\n`;
const fileName = `transkrip-${stamp(data.sent_at)}.txt`;

return [
  {
    json: {
      chat_id: chatId,
      is_file: true,
      file_name: fileName,
      transcript_text: '',
    },
    binary: {
      data: {
        data: Buffer.from(content, 'utf8').toString('base64'),
        mimeType: 'text/plain',
        fileName,
        fileExtension: 'txt',
      },
    },
  },
];

// Susun pesan error yang dikirim ke Telegram.
// Semua jalur error bertemu di sini; tahap & kalimat ramahnya sudah diisi oleh
// node "Stage: ..." tepat sebelum node ini.
const item = $input.first().json ?? {};

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const detail = String(
  item.error?.message ??
    item.error?.description ??
    item.error?.error ??
    (typeof item.error === 'string' ? item.error : '') ??
    item.message ??
    '',
).trim();

const lines = [
  `⚠️ <b>${escapeHtml(item.error_stage ?? 'Pemrosesan gagal')}</b>`,
  escapeHtml(item.error_message ?? 'Coba kirim ulang rekamannya ya.'),
];

if (detail) {
  lines.push('', `<code>${escapeHtml(detail.slice(0, 300))}</code>`);
}

let chatId = item.chat_id ?? '';
if (!chatId) {
  try {
    chatId = $('Extract Audio').first().json.chat_id;
  } catch (error) {
    chatId = '';
  }
}

return [
  {
    json: {
      chat_id: chatId,
      error_text: lines.join('\n'),
    },
  },
];
